const token = $env.GITHUB_TOKEN;
if (!token) {
  throw new Error('GITHUB_TOKEN is not configured in n8n environment');
}

const url = new URL('https://api.github.com/repos/pmwasim/bizOS/actions/runs');
url.searchParams.set('status', 'completed');
url.searchParams.set('per_page', '10');

const response = await fetch(url, {
  headers: {
    Accept: 'application/vnd.github+json',
    Authorization: `Bearer ${token}`,
    'X-GitHub-Api-Version': '2022-11-28',
  },
});

if (!response.ok) {
  throw new Error(`GitHub API ${response.status}: ${await response.text()}`);
}

return [{ json: await response.json() }];

const runs = $input.first().json.workflow_runs ?? [];
const staticData = $getWorkflowStaticData('global');
if (!staticData.notifiedRunIds) {
  staticData.notifiedRunIds = {};
}

const failures = runs.filter((run) => {
  if (run.conclusion !== 'failure' && run.conclusion !== 'cancelled') {
    return false;
  }
  if (staticData.notifiedRunIds[String(run.id)]) {
    return false;
  }
  return true;
});

return failures.map((run) => ({
  json: {
    event: 'ci.failure',
    source: 'github-actions-poll',
    idempotencyKey: `gh-run-${run.id}`,
    repo: 'pmwasim/bizOS',
    workflow: run.name,
    runId: run.id,
    runUrl: run.html_url,
    branch: run.head_branch,
    sha: run.head_sha?.slice(0, 7),
    conclusion: run.conclusion,
    actor: run.actor?.login ?? 'unknown',
    createdAt: run.created_at,
  },
}));

const staticData = $getWorkflowStaticData('global');
if (!staticData.notifiedRunIds) {
  staticData.notifiedRunIds = {};
}
staticData.notifiedRunIds[String($json.runId)] = $now.toISO();

// Keep map bounded
const keys = Object.keys(staticData.notifiedRunIds);
if (keys.length > 200) {
  for (const key of keys.slice(0, keys.length - 200)) {
    delete staticData.notifiedRunIds[key];
  }
}

return [{ json: { ...$json, status: 'routed' } }];
